-- ============================================================================
-- GARMIN TRAINING HUB — MIGRAÇÃO 120: Reformula a aula "Portfólio de
-- Produtos" (lição MARQ) em treinamento de produto + vendas completo
-- ============================================================================
-- Pedido do usuário (2026-09-15): a 3ª (e última) lição do módulo "Portfólio
-- de Produtos" (Zona Explorador) só cobria a linha MARQ, de forma resumida.
-- O módulo tem só 3 lições (Forerunner, Fenix, MARQ, ver sql/030) — o
-- usuário decidiu concentrar TUDO nesta 3ª lição em vez de criar lições
-- novas: organização do portfólio, resumo de Forerunner/Fenix (que já têm
-- lição própria, aqui só recapitula), MARQ completo, e categorias que nunca
-- tinham conteúdo de treinamento nenhum (Edge, Varia, Rally, HRM, Blaze),
-- mais conceitos técnicos, raciocínio de venda, um quiz de associação
-- (tipo de bloco 'match_quiz', já existente e usado em outras lições — não
-- foi criado nada novo) e um quiz final.
--
-- Sem inventar dado: todo texto de produto (Forerunner, Fenix, Edge, Varia,
-- Rally, HRM) usa o `dest`/texto já cadastrado em content_library (categoria
-- 'produto', sql/seeds/040). O Blaze usa só os fatos já cadastrados na
-- Academia de Produtos (sql/090_academia_seed_hrm_blaze_cirqa.sql) — nenhuma
-- especificação nova foi adicionada, e propositalmente NÃO inclui "distância"
-- nem "recuperação" entre as métricas do Blaze por não estarem consistentes
-- nas duas fontes cadastradas (deep_dive vs. página da Academia).
--
-- O "Quiz Final" reaproveita o quiz já existente pra este módulo (slug
-- 'produtos', 10 perguntas — ver sql/097) via bloco 'quiz_embutido', em vez
-- de criar um quiz novo. Só ACRESCENTA (nunca remove/edita) 7 perguntas
-- novas testando raciocínio comercial sobre o conteúdo novo desta lição
-- (Rally, Varia, Blaze, Fenix, HRM, MARQ) — inserção pura, sem tocar nas 10
-- perguntas antigas, porque UPDATE/DELETE nelas arriscaria referências de
-- quiz_attempts/quiz_answers de quem já respondeu.
-- ============================================================================

do $$
declare
  v_quiz_id uuid;
  v_body jsonb;
  v_q_id uuid;
begin
  select id into v_quiz_id from quizzes
   where brand_id = (select id from brands where slug = 'garmin') and slug = 'produtos';

  if v_quiz_id is null then
    raise exception 'Quiz "produtos" não encontrado — rode sql/seeds/020_quizzes.sql antes desta migração.';
  end if;

  -- corpo da lição (17 seções do roteiro do usuário, quizId do bloco
  -- quiz_embutido preenchido dinamicamente com o id real do quiz acima)
  v_body := '[{"type":"texto_rico","html":"<h3>Conheça o portfólio Garmin</h3><p>Agora que você já aprendeu a identificar o perfil do cliente, é hora de conhecer as soluções Garmin.</p><p>A Garmin vai muito além dos relógios. O portfólio reúne produtos para corrida, triathlon, outdoor, ciclismo, natação, mergulho, golfe, navegação, sensores de performance e até soluções específicas para o monitoramento de cavalos.</p><p>O segredo não é decorar todos os produtos. É entender qual necessidade cada categoria atende.</p><p>São sete grandes frentes: relógios esportivos, ciclismo, natação e performance, mergulho, golfe, navegação e outras soluções (como o Garmin Blaze).</p><p><strong>Primeiro entenda a necessidade. Depois pense no produto.</strong></p>"},{"type":"texto_rico","html":"<hr class=\"cb-topic-divider\"><h3>Relógios esportivos</h3><p>Os relógios Garmin são organizados em diferentes linhas porque os clientes também têm necessidades diferentes. Um corredor iniciante não precisa do mesmo produto que um triatleta de alta performance — e quem pratica trilha ou vários esportes pode precisar de recursos específicos.</p><p><strong>Forerunner</strong> → corrida e triathlon &nbsp;·&nbsp; <strong>Fēnix</strong> → multiesporte e outdoor &nbsp;·&nbsp; <strong>MARQ</strong> → luxo + performance</p><p>Forerunner e Fēnix você já viu em detalhe nas aulas anteriores — toque nos cards abaixo pra recapitular rápido antes de entrar na MARQ.</p>"},{"type":"flip_card","columns":2,"cards":[{"title":"Entrada","subtitle":"Forerunner 70 e 55","frontText":"Primeiro contato com GPS e frequência cardíaca, sem complicação.","backLabel":"Quando oferecer","backText":"Cliente nunca usou relógio esportivo e quer simplicidade — começando a correr ou voltando depois de um tempo parado."},{"title":"Intermediário","subtitle":"Forerunner 165 e 170","frontText":"Tela AMOLED e mais recursos de treino, ainda sem GPS multibanda.","backLabel":"Quando oferecer","backText":"Já corre com regularidade e quer uma tela melhor e mais dados de treino, sem pagar pelo multibanda."},{"title":"Intermediário avançado a avançado","subtitle":"Forerunner 265 e 570","frontText":"GPS multibanda, Training Readiness e treino intervalado de precisão.","backLabel":"Quando oferecer","backText":"Treina com frequência, fala em ritmo e PR, e quer métricas mais avançadas de performance."},{"title":"Alta performance a topo de linha","subtitle":"Forerunner 955, 965 e 970","frontText":"Bateria longa, mapas topográficos e materiais premium.","backLabel":"Quando oferecer","backText":"Compete ou treina em alto nível, já tem um Garmin e busca upgrade de bateria, mapas ou acabamento."}]},{"type":"texto_rico","html":"<hr class=\"cb-topic-divider\"><h3>Fēnix: multiesporte e outdoor</h3><p>O fēnix é indicado para quem quer um relógio preparado para muito mais do que corrida — treinamento, aventura, navegação e outdoor numa proposta premium.</p>"},{"type":"flip_card","columns":3,"cards":[{"title":"Fēnix E","subtitle":"Entrada","frontText":"AMOLED e mapas TopoActive, sem alto-falante nem GPS multibanda.","backLabel":"Quando oferecer","backText":"Quer entrar na linha Fēnix sem pagar pelos recursos mais avançados."},{"title":"Fēnix 8","subtitle":"Premium / Outdoor","frontText":"O multiesporte definitivo: alto-falante, microfone, mergulho, trilha e corrida.","backLabel":"Quando oferecer","backText":"Pratica mais de um esporte ou valoriza resistência, navegação e recursos completos num relógio só."},{"title":"Fēnix 8 AMOLED Sapphire","subtitle":"Premium","frontText":"Mesma base do Fēnix 8, com cristal de safira e acabamento superior.","backLabel":"Quando oferecer","backText":"Quer o topo da linha Fēnix e valoriza durabilidade e acabamento acima da média."}]},{"type":"texto_rico","html":"<hr class=\"cb-topic-divider\"><h3>MARQ: luxo + performance</h3><p>A MARQ ocupa uma posição diferente dentro do portfólio.</p><p>Aqui, além da performance, entram materiais premium, acabamento, exclusividade e posicionamento de luxo. É uma linha para um cliente que também valoriza a experiência e a presença do produto no pulso.</p><p><strong>Não apresente a MARQ apenas como um relógio com mais recursos.</strong> O diferencial está na combinação entre tecnologia Garmin, materiais premium e posicionamento de luxo.</p>"},{"type":"accordion","items":[{"title":"MARQ Commander (Gen 2) — para quem é, o que entrega, como apresentar","html":"<p><strong>Para quem é:</strong> cliente que combina alto desempenho com presença no pulso — quer tecnologia de ponta, mas também estética.</p><p><strong>O que entrega:</strong> caixa em titânio e pulseira em couro italiano, estética militar sofisticada, GPS multibanda, mapas completos e modo tático.</p><p><strong>O que diferencia:</strong> é o único da linha com essa estética tática/militar — combina robustez com acabamento de luxo.</p><p><strong>Como apresentar:</strong> pense em quem já usa ou usaria um Fēnix, mas quer um passo além em material e exclusividade.</p>"},{"title":"MARQ Athlete (Gen 2) — para quem é, o que entrega, como apresentar","html":"<p><strong>Para quem é:</strong> atleta de corrida e triathlon de alto nível que não abre mão de estilo.</p><p><strong>O que entrega:</strong> titânio com pulseira sport premium, GPS multibanda, métricas avançadas de treino e Training Readiness.</p><p><strong>O que diferencia:</strong> é a MARQ voltada especificamente para performance esportiva, não outdoor nem golfe.</p><p><strong>Como apresentar:</strong> pense nele como a opção do cliente que já pensaria num Forerunner topo de linha, mas quer também exclusividade de material.</p>"},{"title":"MARQ Golfer Carbon (Gen 2) — para quem é, o que entrega, como apresentar","html":"<p><strong>Para quem é:</strong> golfista que valoriza tanto o jogo quanto o status do equipamento.</p><p><strong>O que entrega:</strong> caixa em fibra de carbono com acabamento premium, mapas de mais de 42.000 campos de golfe, modo caddie digital, estatísticas de jogo e distâncias automáticas.</p><p><strong>O que diferencia:</strong> é o único relógio de golfe no patamar de luxo real — não existe equivalente Approach com esse posicionamento.</p><p><strong>Como apresentar:</strong> não é só “um Approach mais caro” — é a opção de quem já joga com equipamento premium e quer o relógio à altura.</p>"}]},{"type":"texto_rico","html":"<hr class=\"cb-topic-divider\"><h3>Lifestyle: saúde e estilo no dia a dia</h3><p>Nem todo cliente busca performance esportiva. Parte do portfólio é pensada pra quem quer acompanhar saúde e bem-estar com um relógio que também funciona como peça do dia a dia.</p><p>Pergunte primeiro se o cliente já pratica algum esporte com regularidade — se não, essas opções costumam fazer mais sentido que um Forerunner ou Fēnix.</p>"},{"type":"flip_card","columns":2,"cards":[{"title":"Lily 2","subtitle":"Design joia","frontText":"O menor relógio Garmin. Elegância e saúde no pulso.","backLabel":"Quando oferecer","backText":"Cliente quer algo pequeno e discreto pro dia a dia, ou está buscando um presente — não fala em treino nem GPS."},{"title":"Lily 2 Active","subtitle":"Estilo + GPS","frontText":"Lily com GPS integrado e resistência à água. Corrida com estilo.","backLabel":"Quando oferecer","backText":"Um passo além do Lily 2: o cliente também corre ou caminha e quer registrar isso, sem abrir mão do design."},{"title":"Venu 4","subtitle":"AMOLED premium","frontText":"AMOLED premium com saúde feminina completa. Até 9 dias de bateria.","backLabel":"Quando oferecer","backText":"Quer tela grande e recursos completos de saúde, sem o peso de uma linha esportiva como Forerunner ou Fēnix."},{"title":"Vivoactive 6","subtitle":"Academia e dia a dia","frontText":"80+ modos esportivos e músicas offline. Versátil pra academia e o dia a dia.","backLabel":"Quando oferecer","backText":"Varia entre academia, caminhada e outras atividades sem foco único em corrida — quer um relógio “para tudo”."}]},{"type":"texto_rico","html":"<hr class=\"cb-topic-divider\"><h3>Garmin é muito mais do que relógios</h3><p>A conversa de venda não deveria terminar no relógio. Boa parte das oportunidades reais está nos acessórios e nas outras categorias do portfólio.</p>"},{"type":"card_grid","columns":3,"items":[{"title":"Ciclocomputadores — Edge","text":"Para quem quer levar os dados e a navegação para o guidão da bicicleta.","tags":[]},{"title":"Radares — Varia","text":"Para ciclistas que querem aumentar a percepção dos veículos que se aproximam por trás.","tags":[]},{"title":"Medidores de potência — Rally","text":"Para quem quer acompanhar o esforço produzido na pedalada em watts.","tags":[]},{"title":"Sensores cardíacos — HRM","text":"Para quem quer dados de frequência cardíaca mais específicos ou precisa ampliar os dados do relógio.","tags":[]},{"title":"Mergulho — Descent","text":"Computadores de mergulho completos, com smartwatch fora da água.","tags":[]},{"title":"Golfe — Approach","text":"Distâncias automáticas e recursos de jogo direto no pulso.","tags":[]},{"title":"Navegação — GPSMAP / Zūmo","text":"Soluções específicas para trilha, náutica e viagens de moto.","tags":[]},{"title":"Monitoramento equino — Blaze","text":"Para cavaleiros, proprietários e treinadores que acompanham o desempenho do cavalo.","tags":[]}]},{"type":"texto_rico","html":"<hr class=\"cb-topic-divider\"><h3>Edge: performance no guidão</h3><p>Os Edge são ciclocomputadores desenvolvidos para quem quer transformar a bicicleta numa experiência mais completa de treinamento, navegação e performance.</p><p>Aqui, o raciocínio comercial é diferente dos relógios. A linha vai do Edge 540 (entrada) até o 1050 (topo), passando pelo 840 e 1040 — mas antes de falar de modelo, pergunte primeiro:</p><ul class=\"cb-checklist\"><li>O cliente pedala por lazer ou treina?</li><li>Usa estrada, MTB ou gravel?</li><li>Precisa de navegação?</li><li>Quer acompanhar potência e outros dados?</li><li>Pedala por longos períodos?</li></ul>"},{"type":"tabs","items":[{"label":"Edge 550","title":"Edge 550","text":"Sucessor do 540 — soma tela de 1000 nits, speaker e Cycling Coach.","note":"Indicado para: ciclista intermediário que quer upgrade de tela e recursos, sem saltar pro topo de linha."},{"label":"Edge 850","title":"Edge 850","text":"Versão compacta do 1050 — mesma tela de 1000 nits e speaker, sem o tamanho 3.5\".","note":"Indicado para: ciclista dedicado que quer os recursos do topo de linha num corpo menor."},{"label":"Edge 1050","title":"Edge 1050","text":"Tela 3.5\" 1000 nits, Garmin Pay, buzina e alerta de perigo — topo absoluto da linha.","note":"Indicado para: ciclista elite ou que pedala em grupo/trânsito e valoriza tela grande e recursos de segurança."}]},{"type":"texto_rico","html":"<p><strong>Como identificar oportunidade de upgrade:</strong> se o cliente já pedala com um Edge de entrada (540) e menciona querer navegação melhor, tela maior ou mais autonomia, vale apresentar o 1040 ou 1050. Não empurre o topo de linha por padrão — pergunte primeiro o que ele já sente falta.</p><hr class=\"cb-topic-divider\"><h3>Varia: segurança para o ciclista</h3><p>O Varia complementa a experiência de quem pedala na estrada com percepção e segurança. O radar traseiro RTL515 detecta veículos a até 140 metros e alerta direto no relógio ou no Edge.</p><p><strong>Se o cliente já está comprando ou usando um Edge, pergunte se ele já utiliza algum recurso de segurança traseira.</strong> Boa oportunidade de venda complementar — não trate o Varia como acessório opcional qualquer.</p><hr class=\"cb-topic-divider\"><h3>Rally: potência no pedal</h3><p>Os pedais Rally (RK 200) medem a potência produzida durante a pedalada — compatíveis com qualquer pedivela.</p><p>Pense em potência como a forma mais objetiva de medir o esforço do ciclista em watts, sem depender de percepção de esforço ou frequência cardíaca. Vale oferecer quando o cliente já fala em treino estruturado ou preparação para prova.</p>"},{"type":"texto_rico","html":"<hr class=\"cb-topic-divider\"><h3>HRM: quando o relógio pode ganhar mais dados</h3><p>Os sensores cardíacos podem complementar o relógio Garmin, fornecendo dados de frequência cardíaca e, dependendo do modelo, outras informações de desempenho.</p><p><strong>Se o cliente treina com frequência e busca dados mais específicos de esforço, vale investigar se um sensor cardíaco faz sentido.</strong> Não apresente o HRM apenas como \"uma cinta que mede batimentos\" — é uma oportunidade real de venda complementar.</p>"},{"type":"tabs","items":[{"label":"HRM 200","title":"HRM 200","text":"Monitor cardíaco de peito, com precisão superior ao óptico do pulso.","note":"Ofereça quando o cliente treina em alta intensidade ou já reclamou de leitura instável."},{"label":"HRM 600","title":"HRM 600","text":"Monitor premium, com dinâmicas de corrida, HRV e armazenamento próprio — grava mesmo debaixo d''água.","note":"Ofereça quando o cliente já treina estruturado e quer métricas avançadas, inclusive na natação."}]},{"type":"texto_rico","html":"<hr class=\"cb-topic-divider\"><h3>BLAZE: uma solução diferente dentro do portfólio Garmin</h3><p>Quando aparecer um cliente ligado à equitação, não pense automaticamente em relógio.</p><p>O Garmin Blaze é um sistema de monitoramento de bem-estar equino, desenvolvido para cavaleiros, proprietários e treinadores que querem acompanhar dados do cavalo durante o treinamento e outras atividades. Usa um sensor encaixado numa faixa posicionada na base da cauda do cavalo, e acompanha dados como frequência cardíaca, passada e andamento. Tem aplicativo próprio e pode mostrar dados em relógios Garmin compatíveis.</p><p>O Blaze abre uma conversa diferente: monitoramento do cavalo, treinamento e acompanhamento de dados — não é uma linha de relógios.</p><p><strong>Pergunta-chave:</strong> \"Você acompanha o desempenho do seu cavalo durante os treinos?\"</p>"},{"type":"timeline","reveal":true,"items":[{"label":"Para quem é?","text":"Cavaleiros, proprietários e treinadores."},{"label":"O que resolve?","text":"Monitoramento do cavalo durante treinamento e outras atividades."},{"label":"Qual o diferencial?","text":"Solução Garmin específica para monitoramento equino, com sensor e aplicativo próprios."},{"label":"Como identificar a oportunidade?","text":"Cliente ligado à equitação, treinamento de cavalos ou acompanhamento de desempenho equino."}]},{"type":"texto_rico","html":"<hr class=\"cb-topic-divider\"><h3>Não pense apenas no produto principal</h3><p>Boa parte da oportunidade comercial está em somar uma necessidade adicional ao produto principal:</p>"},{"type":"metric_card_grid","columns":2,"items":[{"name":"Relógio + HRM","definition":"Mais dados de frequência cardíaca e desempenho.","tip":"Pergunte se o cliente já sentiu leitura instável no pulso durante treino intenso."},{"name":"Edge + Varia","definition":"Computador de ciclismo + segurança.","tip":"Sempre pergunte sobre segurança pra quem pedala na rua ou estrada com tráfego."},{"name":"Edge + Rally","definition":"Navegação e dados de potência.","tip":"Vale quando o cliente já fala em treino estruturado ou preparação pra prova."},{"name":"Relógio + acessórios","definition":"Expanda os dados e a experiência do cliente.","tip":"Produto principal + necessidade adicional = oportunidade de venda complementar."}]},{"type":"texto_rico","html":"<p><strong>Produto principal + necessidade adicional = oportunidade de venda complementar.</strong></p><hr class=\"cb-topic-divider\"><h3>Conceitos técnicos</h3><p>Termos que aparecem com frequência na conversa de venda — explicados em linguagem simples.</p>"},{"type":"metric_card_grid","columns":2,"items":[{"name":"AMOLED","definition":"Tela com cores vivas e alto contraste, parecida com a de um smartphone.","tip":"Explique como \"tela mais bonita e nítida\" — mas costuma gastar mais bateria."},{"name":"GPS multibanda","definition":"Usa duas frequências de satélite ao mesmo tempo, em vez de uma só.","tip":"O traçado da rota fica muito mais preciso em cidade, mata ou perto de prédios altos."},{"name":"SatIQ","definition":"Alterna automaticamente entre os modos de GPS pra economizar bateria sem perder precisão.","tip":"\"O relógio decide sozinho quanto de GPS usar\", sem o cliente configurar nada."},{"name":"Mapas","definition":"Cartografia embarcada no relógio ou dispositivo, sem precisar do celular.","tip":"Bom argumento pra quem faz trilha ou pedala sem sinal de internet."},{"name":"Body Battery","definition":"Indicador de energia do corpo, de 0 a 100, baseado em sono, estresse e atividade.","tip":"\"Um medidor de pilha do corpo\" — ajuda a decidir quando treinar forte ou descansar."},{"name":"Status de treinamento (Training Readiness)","definition":"Estimativa de o quanto o corpo está pronto pra treinar forte naquele dia.","tip":"Use pra clientes que treinam com frequência e querem saber quando forçar ou recuperar."},{"name":"Potência","definition":"Medição do esforço físico em watts, em vez de só velocidade ou frequência cardíaca.","tip":"A métrica mais objetiva do ciclismo — não muda com cansaço, calor ou nervosismo do dia."},{"name":"Radar","definition":"Sensor que detecta objetos se aproximando por trás, como carros numa estrada.","tip":"No Varia, isso vira um alerta visual e sonoro direto no relógio ou Edge."},{"name":"Frequência cardíaca","definition":"Batimentos por minuto, medidos no pulso (óptico) ou no peito (HRM).","tip":"A leitura de peito costuma ser mais precisa em esforço alto que a do pulso."},{"name":"Cristal de safira","definition":"Material de tela mais resistente a arranhões que o vidro comum.","tip":"Bom argumento de durabilidade pra quem usa o relógio intenso no dia a dia ou no trabalho."}]},{"type":"texto_rico","html":"<hr class=\"cb-topic-divider\"><h3>Do produto para a necessidade</h3><p>Na prática, o raciocínio de venda segue sempre a mesma lógica. Veja como isso funciona com um exemplo real de atendimento:</p>"},{"type":"timeline","items":[{"label":"1. Cliente fala","text":"\"Quero melhorar meus treinos de bike.\""},{"label":"2. Você identifica a necessidade","text":"Ciclismo — ele já treina, não é só lazer casual."},{"label":"3. Escolhe a categoria","text":"Edge, pra levar dados e navegação pro guidão."},{"label":"4. Compara os modelos","text":"Nível de treino, se precisa de tela grande, navegação ou potência."},{"label":"5. Apresenta o benefício","text":"O Edge certo pro que ele já falou que precisa — não o mais caro por padrão."},{"label":"6. Avalia venda complementar","text":"Já usa Varia pra segurança? Pensa em medir potência com o Rally?"}]},{"type":"texto_rico","html":"<h4>Quiz de associação — aquecimento</h4><p>Antes do quiz final, relacione cada perfil de cliente com a linha ou produto certo.</p>"},{"type":"match_quiz","pairs":[{"term":"Corredor","definition":"Forerunner"},{"term":"Aventureiro","definition":"Fēnix"},{"term":"Cliente premium","definition":"MARQ"},{"term":"Quer saúde e estilo no dia a dia","definition":"Lifestyle"},{"term":"Ciclista que quer dados no guidão","definition":"Edge"},{"term":"Ciclista preocupado com segurança","definition":"Varia"},{"term":"Ciclista interessado em potência","definition":"Rally"},{"term":"Cliente buscando sensor cardíaco","definition":"HRM"},{"term":"Mergulhador","definition":"Descent"},{"term":"Golfista","definition":"Approach"},{"term":"Cliente ligado à equitação","definition":"Blaze"}]},{"type":"texto_rico","html":"<h4>Quiz final</h4><p>Agora teste seu raciocínio comercial com o quiz do módulo — as perguntas testam se você consegue reconhecer a categoria certa pra cada situação de cliente, não decorar especificação solta.</p>"},{"type":"quiz_embutido","quizId":"","label":"Responder quiz do módulo"}]'::jsonb;
  v_body := jsonb_set(v_body, '{-1,quizId}', to_jsonb(v_quiz_id::text));

  update lessons
     set body = jsonb_build_object('blocks', v_body),
         updated_at = now()
   where id = '7d5e81d0-21a1-426a-9938-7bb667723d3c';

  if not found then
    raise exception 'Lição MARQ (id 7d5e81d0-...) não encontrada — verifique se sql/030 já foi aplicada.';
  end if;

  -- 7 perguntas novas no quiz do módulo, cobrindo o conteúdo novo desta
  -- lição (Rally, Varia, Blaze, Fenix, HRM, MARQ) — puro INSERT, não mexe
  -- nas 10 perguntas existentes (Forerunner/Fenix/MARQ já cobertas por
  -- sql/097). order_index continua depois da última (9).

  insert into questions (quiz_id, body, explanation, order_index)
  values (v_quiz_id, 'Um cliente diz que corre três vezes por semana e quer começar a acompanhar melhor sua evolução. Qual linha deve ser considerada primeiro?', 'Corrida com frequência regular e interesse em evolução é o perfil clássico de Forerunner — o próximo passo é entender se ele já usa GPS pra escolher entre entrada e intermediário.', 10)
  returning id into v_q_id;
  insert into alternatives (question_id, body, is_correct, feedback, order_index) values (v_q_id, 'Forerunner', true, null, 0);
  insert into alternatives (question_id, body, is_correct, feedback, order_index) values (v_q_id, 'Fēnix', false, null, 1);
  insert into alternatives (question_id, body, is_correct, feedback, order_index) values (v_q_id, 'MARQ', false, null, 2);
  insert into alternatives (question_id, body, is_correct, feedback, order_index) values (v_q_id, 'Edge', false, null, 3);

  insert into questions (quiz_id, body, explanation, order_index)
  values (v_quiz_id, 'Um cliente já possui um Garmin e está treinando para uma prova de ciclismo. Ele quer acompanhar potência. Qual oportunidade deve ser investigada?', 'Potência em watts é exatamente o que o Rally mede — é uma venda complementar a um Edge ou relógio que o cliente já tenha.', 11)
  returning id into v_q_id;
  insert into alternatives (question_id, body, is_correct, feedback, order_index) values (v_q_id, 'Rally', true, null, 0);
  insert into alternatives (question_id, body, is_correct, feedback, order_index) values (v_q_id, 'Varia', false, null, 1);
  insert into alternatives (question_id, body, is_correct, feedback, order_index) values (v_q_id, 'HRM', false, null, 2);
  insert into alternatives (question_id, body, is_correct, feedback, order_index) values (v_q_id, 'Descent', false, null, 3);

  insert into questions (quiz_id, body, explanation, order_index)
